    /** كلمات تربط العبارة باحتياج؛ العبارة لا تظهر إلا لما يكون مؤشرها تحت الحد */
    val tags: Map<String, List<String>> = mapOf(
        "hunger" to listOf("جوع", "أكل", "ناكل", "ياكل", "الغدا", "كبسة", "كيك", "عصير", "بسكوت", "يمي", "نفطر", "شوربة", "لذيذ", "الخضار", "تفاح", "موز", "حليب", "ساندويتش", "سندويتش", "عطشان", "تشرب", "أشرب", "مويه", "الثلاجة", "دجاج", "الفرن", "حلاو", "جزر"),
        "clean" to listOf("وصخ", "ريحتك", "عرق", "نغسل", "اغسل", "أغسل", "أتروش", "فرّش", "فرش", "أسنان", "صابون", "فقاعات", "نظيف", "مويه", "شاور"),
        "health" to listOf("تعبان", "تعور", "تعوّر", "يعوّر", "طحت", "دوا", "حرارة", "مريض", "كح", "لصقة"),
        "sleep" to listOf("نعسان", "نوم", "نام", "ارتاح", "سرير!", "السرير"),
    )

    /** الاحتياجات اللي تتكلم عنها العبارة */
    fun needsOf(line: String): List<String> = tags.filter { (_, ws) -> ws.any { line.contains(it) } }.keys.toList()

    /** العبارة مسموحة لو كل احتياج تذكره مؤشره تحت الحد عند الطفل */
    fun fits(store: Store, kidId: String, line: String): Boolean = needsOf(line).all { store.need(kidId, it) < Needs.LOW }

    fun doneLine(kid: Kid, kind: String): String? = done[group(kid)]?.get(kind)?.randomOrNull()

    /** الأنشطة المتاحة للطفل في الغرفة: النشاط المرتبط باحتياج ما يصير إلا لما يكون المؤشر ناقص */
    fun forKid(store: Store, kid: Kid, room: String): List<Act> = all.filter { a ->
        a.room == room && a.lines.containsKey(group(kid)) &&
            (a.who == "all" || (a.who == "big" && !kid.toddler) || (a.who == "t" && kid.toddler)) &&
            (a.meter == null || store.need(kid.id, a.meter) < Needs.LOW)
    }
}
